mapper.select:
select l.id, l.employee_id, l.leave_type, l.start_date, l.end_date, l.days, l.reason, l.status, l.approve_user_id, l.approve_time, l.approve_remark, l.create_time, e.name as employee_name, e.emp_no, d.name as dept_name, u.real_name as approve_user_name from sys_leave l left join sys_employee e on e.id = l.employee_id and e.deleted = 0 left join sys_department d on d.id = e.dept_id and d.deleted = 0 left join sys_user u on u.id = l.approve_user_id and u.deleted = 0
l.deleted = 0
and l.employee_id = #{query.employeeId}
and l.employee_id in
#{empId}
and l.status = #{query.status}
and l.status <> 3
and e.name like concat('%', #{query.employeeName}, '%')
order by l.id desc
